def main() -> None:
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    with OUTPUT.open("w", encoding="utf-8") as handle:
        count = 0
        for seed_idx, (category, prompts, response) in enumerate(SEEDS):
            for variant_idx, prompt in enumerate(prompts):
                record = {"id": f"keilinks-seed-{seed_idx:04d}-{variant_idx}",
                    "group_id": f"keilinks-seed-{seed_idx:04d}",
                    "source": "keilinks_curated_v4", "category": category,
                    "license": "proprietary-keilinks", "quality": "human_curated",
                    "messages": [{"role":"system","content":SYSTEM},
                                 {"role":"user","content":prompt},
                                 {"role":"assistant","content":response}]}
                handle.write(json.dumps(record, ensure_ascii=False) + "\n"); count += 1
    print(f"{count} conversas curadas salvas em {OUTPUT}")


if __name__ == "__main__": main()
